"""Build the standalone visual prototype/data; never edits runtime game files."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
rows = [
    ('shack','Starter Shack',0,'common','cozy',18,14,1),
    ('cottage','Cosy Cottage',35000,'common','cozy',26,20,1),
    ('townhouse','Brick Townhouse',120000,'rare','classic',20,16,3),
    ('gardenbungalow','Garden Bungalow',250000,'rare','cozy',32,25,1),
    ('villa','Suburban Villa',400000,'rare','classic',33,24,2),
    ('coastalvilla','Coastal Villa',750000,'rare','classic',36,30,2),
    ('manor','Stone Manor',1400000,'epic','classic',34,28,3),
    ('hilltopmansion','Hilltop Mansion',2500000,'epic','classic',40,34,3),
    ('modern','Midnight Modern',5000000,'epic','modern',44,32,2),
    ('sunsetvilla','Sunset Sky Villa',8000000,'epic','modern',42,34,5),
    ('neontower','Neon Tower',15000000,'legendary','modern',24,22,6),
    ('emeraldchateau','Emerald Chateau',25000000,'legendary','royal',48,36,4),
    ('palace','Marble Palace',40000000,'legendary','royal',46,30,3),
    ('skycastle','Sky Castle',80000000,'legendary','royal',40,34,5),
    ('royalobservatory','Royal Observatory',150000000,'legendary','royal',44,38,4),
    ('skylinepenthouse','Skyline Penthouse',300000000,'legendary','modern',40,38,8),
    ('imperialestate','Imperial Estate',600000000,'legendary','royal',56,44,6),
    ('celestialcitadel','Celestial Citadel',1000000000,'legendary','royal',52,46,7),
]
existing={'shack','cottage','townhouse','villa','manor','modern','neontower','palace','skycastle'}
houses=[dict(zip(('id','name','price','rarity','interiorMood','width','depth','storeys'),r),existing=r[0] in existing) for r in rows]
(ROOT/'houses/catalogue-design.json').write_text(json.dumps(houses,indent=2),encoding='utf-8')
html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>House catalogue • visual prototype</title>
<style>
:root{--ink:#29201b;--slab:#362c25;--deep:#1c1613;--muted:#6b5445;--muted-light:#c4b29c;--sand:#f5e1c6;--paper:#fff7e8;--paper-deep:#eddcc2;--gold:#ffcb3d;--good:#3bd181;--owned:#ade7bd;--buy:#ffe5a0;--dear:#dbcab4;--locked:#e0b8f2;--common:#ac9f91;--rare:#4093e6;--epic:#b561ff;--legendary:#ffcb3d;--scale:1}
*{box-sizing:border-box}body{margin:0;background:var(--slab);color:var(--ink);font-family:'Trebuchet MS',Arial,sans-serif;min-height:100vh;padding:16px;display:flex;align-items:center;justify-content:center}button,select,input{font:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--rare);outline-offset:3px}button:disabled{cursor:default}
.workspace{width:100%;display:flex;flex-direction:column;align-items:center;gap:12px}.preview-tools{width:min(1040px,100%);color:var(--paper);display:flex;align-items:center;gap:12px;font-size:12px;flex-wrap:wrap}.preview-tools strong{color:var(--gold);letter-spacing:.06em}.preview-tools a{color:var(--paper)}.preview-tools label{display:flex;gap:5px;align-items:center}.preview-tools select{background:var(--paper);border:0;border-radius:5px;color:var(--ink);padding:5px}.shell{width:min(1040px,100%);height:min(720px,calc(100vh - 102px));min-height:250px;background:var(--sand);border:4px solid var(--ink);border-radius:24px;box-shadow:0 8px 0 var(--deep);display:flex;flex-direction:column;overflow:hidden}.header{height:62px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:2px solid var(--paper-deep);gap:10px}.brand{display:flex;align-items:center;gap:12px}.mark{background:var(--good);width:34px;height:34px;display:grid;place-items:center;border:2px solid var(--ink);border-radius:10px}.mark svg{width:23px}.heading{font-size:23px;font-weight:900;letter-spacing:-.03em}.header small{display:block;color:var(--muted);font-size:11px;margin-top:1px}.balance{padding:7px 12px;background:var(--slab);border-radius:14px;color:var(--gold);font-size:15px;font-weight:900;white-space:nowrap}.coin{display:inline-block;width:12px;height:12px;border:2px solid var(--gold);border-radius:50%;margin-right:5px;box-shadow:inset 0 0 0 2px var(--slab);background:var(--gold)}.close{width:36px;height:36px;border:2px solid var(--ink);border-radius:12px;background:var(--paper);font-size:24px;font-weight:900;flex:none}
.rail{display:flex;gap:8px;overflow-x:auto;flex:none;padding:9px 14px 6px;scrollbar-width:thin}.rail button{padding:8px 14px;border:0;border-radius:10px;color:var(--ink);background:var(--paper-deep);font-size:12px;font-weight:900;white-space:nowrap}.rail .selected{background:var(--good);box-shadow:0 2px 0 var(--ink)}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:9px 16px 11px;flex:none}.filters{display:flex;gap:5px}.filters button{border:0;background:var(--paper);color:var(--ink);border-radius:9px;padding:8px 12px;font-weight:900;font-size:12px}.filters button[aria-pressed=true]{background:var(--slab);color:var(--paper)}.order{font-size:11px;color:var(--muted)}.scroller{overflow-y:auto;overscroll-behavior:contain;flex:1;min-height:0;scrollbar-color:var(--muted) var(--paper-deep);scrollbar-width:thin;padding:8px 14px 14px}.grid{display:grid;grid-template-columns:repeat(auto-fill,calc(156px * var(--scale)));gap:12px;justify-content:center;align-content:start}.slot{width:calc(156px * var(--scale));height:calc(182px * var(--scale))}.card{position:relative;width:156px;height:182px;transform:scale(var(--scale));transform-origin:top left;border:0;border-radius:15px;background:var(--paper);color:var(--ink);padding:0;text-align:left;box-shadow:0 0 0 3px var(--rarity);overflow:visible}.card.legendary{box-shadow:0 0 0 5px var(--rarity)}.card.shown,.card.owned{background:var(--owned)}.card.affordable{background:var(--buy)}.card.toodear{background:var(--dear)}.card.wontfit{background:var(--paper-deep)}.well{position:absolute;left:8px;top:8px;width:140px;height:76px;border-radius:9px;background:var(--slab);overflow:hidden}.well svg{width:100%;height:100%;display:block}.well img{height:100%;width:155%;object-fit:cover;object-position:left 46%;display:block}.rarity{position:absolute;bottom:4px;left:5px;border-radius:5px;padding:3px 5px;font-size:9px;line-height:10px;background:var(--rarity);color:#000;font-weight:900}.state-mark{position:absolute;right:5px;top:4px;background:var(--paper);color:var(--ink);padding:2px 5px;font-size:9px;font-weight:900;border-radius:5px}.name{position:absolute;top:89px;left:8px;width:140px;height:34px;font-size:14px;font-weight:900;line-height:16px;display:flex;align-items:center}.price{position:absolute;left:8px;top:126px;width:140px;height:19px;border-radius:8px;background:var(--slab);color:var(--gold);font-size:11px;font-weight:900;display:flex;align-items:center;justify-content:center;gap:4px}.price .coin{width:9px;height:9px;margin:0}.action{position:absolute;left:8px;top:150px;width:140px;height:24px;border-radius:7px;background:var(--slab);color:var(--paper);font-size:11px;font-weight:900;display:flex;align-items:center;justify-content:center;letter-spacing:.01em}.shown .action{background:var(--ink);color:var(--paper)}.affordable .action{background:var(--gold);color:var(--ink)}.wontfit .action,.toodear .action{background:transparent;color:var(--ink)}.statusline{height:34px;flex:none;padding:9px 17px;color:var(--muted);font-size:11px;border-top:1px solid var(--paper-deep);display:flex;justify-content:space-between;gap:8px}.empty{grid-column:1/-1;background:var(--paper);padding:24px;border-radius:15px;text-align:center;color:var(--muted);font-size:14px}.hint{color:var(--muted-light);font-size:11px;text-align:center}.toast{position:fixed;bottom:18px;background:var(--ink);color:var(--paper);border:2px solid var(--paper);border-radius:14px;padding:12px 18px;font-size:13px;max-width:calc(100vw - 24px);display:none;z-index:10}.toast.on{display:block}.shell.closed{display:none}.reopen{display:none;background:var(--gold);border:2px solid var(--ink);border-radius:12px;padding:15px 24px;font-weight:900}.reopen.on{display:block}
@media(max-height:700px){:root{--scale:.78}body{padding:10px}.workspace{gap:8px}.shell{height:calc(100vh - 82px);border-radius:20px}.header{height:48px;padding:0 14px}.heading{font-size:19px}.header small{display:none}.rail{padding-top:6px;padding-bottom:4px}.rail button{padding:6px 12px}.toolbar{padding:6px 14px 8px}.statusline{height:28px;padding-top:6px}.hint{display:none}}
@media(max-width:560px){:root{--scale:.78}body{padding:8px}.preview-tools{gap:7px}.preview-tools strong{width:100%}.shell{height:calc(100vh - 125px)}.header{padding:0 12px}.heading{font-size:20px}.brand{gap:6px}.mark{display:none}.balance{font-size:12px;padding:7px}.toolbar{padding:8px 12px}.order{font-size:10px}.filters button{padding:8px 10px}.statusline{font-size:10px}.statusline span:last-child{display:none}.grid{gap:12px}.scroller{padding-left:12px;padding-right:12px}}
@media(max-height:420px){.preview-tools{display:none}.shell{height:calc(100vh - 20px)}.header{height:40px}.rail{padding-top:4px;padding-bottom:3px}.rail button{padding:4px 10px}.toolbar{padding:4px 12px 6px}.filters button{padding:5px 10px}.statusline{height:24px;padding-top:4px}.workspace{gap:0}}
</style></head><body><div class="workspace"><div class="preview-tools"><strong>DESIGN PREVIEW · 4b.3</strong><label>Coins <select id="coins"><option value="2500000">2.5M</option><option value="0">0</option><option value="25000000">25M</option><option value="1000000000">1B</option></select></label><label>Capacity <select id="capacity"><option value="96904045">96.9M</option><option value="500000">500K</option><option value="1241000000">1.241B</option></select></label><button id="reset">Reset demo</button><a href="../index.html">Design package</a></div>
<main class="shell" aria-label="House catalogue"><header class="header"><div class="brand"><span class="mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M2 11L12 2l10 9M5 9v12h14V9M10 21v-7h4v7"/></svg></span><div><div class="heading">MAKE YOURSELF AT HOME</div><small>Your trophies come with you.</small></div></div><div class="balance"><span class="coin"></span><span id="balance"></span></div><button class="close" aria-label="Close shop">×</button></header>
<nav class="rail" aria-label="Shop categories"><button>Everything</button><button>Upgrades</button><button class="selected">Home</button><button>Rides</button><button>Items</button><button>Worn</button><button>Crates</button></nav>
<section class="toolbar"><div class="filters" aria-label="House filters"><button data-filter="all" aria-pressed="true">All <span id="allcount"></span></button><button data-filter="owned" aria-pressed="false">Owned</button><button data-filter="affordable" aria-pressed="false">Affordable</button></div><div class="order">PRICE: LOW → HIGH</div></section>
<section class="scroller" aria-label="Houses"><div class="grid"></div></section><footer class="statusline"><span id="count"></span><span>Buy once. Move in whenever you like.</span></footer></main><button class="reopen">Open house catalogue</button><div class="hint">Interactive mockup • sample balances only • final game uses real model previews and Theme fonts</div></div><div role="status" class="toast"></div>
<script>
const houses=__DATA__;
const originalOwned=['shack','cottage','villa','neontower'];let owned=new Set(originalOwned),shown='villa',coins=2500000,capacity=96904045,filter='all';
const rarityColors={common:'#ac9f91',rare:'#4093e6',epic:'#b561ff',legendary:'#ffcb3d'};
function fmt(n){return n>=1e9?(n/1e9).toFixed(2).replace(/\.?0+$/,'')+'B':n>=1e6?(n/1e6).toFixed(2).replace(/\.?0+$/,'')+'M':n>=1e3?(n/1e3).toFixed(1).replace(/\.?0+$/,'')+'K':String(n)}
function state(h){if(h.id===shown)return 'shown';if(owned.has(h.id))return 'owned';if(h.price>capacity)return 'wontfit';return coins>=h.price?'affordable':'toodear'}
function art(h){if(!h.existing)return `<img alt="${h.name} concept" src="../houses/${h.id}.png">`;let colors=h.room==='royal'?['#eddcc2','#6b5445']:h.room==='modern'?['#6b5445','#29201b']:['#eddcc2','#6b5445'];let ht=Math.min(48,18+h.storeys*5),y=66-ht;let windows='';for(let r=0;r<Math.min(h.storeys,4);r++)for(let x of [42,65,88])windows+=`<rect x="${x}" y="${y+6+r*10}" width="12" height="7" fill="${r===0?'#ffcb3d':'#4093e6'}" rx="1"/>`;return `<svg viewBox="0 0 140 76" role="img" aria-label="${h.name} silhouette placeholder"><path d="M24 66h96v5H24z" fill="#29201b"/><rect x="32" y="${y}" width="78" height="${ht}" fill="${colors[0]}"/><path d="M27 ${y}L70 ${Math.max(3,y-17)}l45 ${Math.min(17,y-3)}z" fill="${colors[1]}"/>${windows}<rect x="61" y="53" width="18" height="14" rx="1" fill="#29201b"/></svg>`}
function label(h,s){return {shown:'✓ LIVING HERE',owned:'MOVE IN',affordable:'BUY',toodear:'NEED '+fmt(Math.max(0,h.price-coins)),wontfit:'GROW YOUR PIG'}[s]}
function render(){document.querySelector('#balance').textContent=fmt(coins);document.querySelector('#allcount').textContent=houses.length;const list=houses.filter(h=>filter==='all'||filter==='owned'&&owned.has(h.id)||filter==='affordable'&&state(h)==='affordable');document.querySelector('.grid').innerHTML=list.map(h=>{const s=state(h);return `<div class="slot"><button class="card ${h.rarity} ${s}" data-id="${h.id}" data-state="${s}" style="--rarity:${rarityColors[h.rarity]}" aria-label="${h.name}, ${h.price?fmt(h.price)+' coins':'free'}, ${label(h,s)}" ${s==='shown'?'disabled':''}><div class="well">${art(h)}<span class="rarity">${h.rarity.toUpperCase()}</span>${s==='owned'?'<span class="state-mark">OWNED</span>':s==='shown'?'<span class="state-mark">SHOWN</span>':''}</div><div class="name">${h.name}</div><div class="price">${h.price?'<i class="coin"></i>'+fmt(h.price):'FREE'}</div><div class="action">${label(h,s)}</div></button></div>`}).join('')||'<div class="empty">No houses match this filter.<br>Choose All to see the catalogue.</div>';document.querySelector('#count').textContent=`${list.length} shown · ${owned.size} owned`;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===filter));document.querySelectorAll('.card').forEach(b=>b.onclick=()=>activate(b.dataset.id))}
let toastTimer;function tell(msg){let el=document.querySelector('.toast');el.textContent=msg;el.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('on'),4000)}
function activate(id){let h=houses.find(h=>h.id===id),s=state(h);if(s==='owned'){shown=id;tell('Moved into '+h.name+' · demo only')}else if(s==='affordable'){coins-=h.price;owned.add(id);shown=id;tell('Bought '+h.name+' · demo only')}else if(s==='wontfit'){tell('This house costs '+fmt(h.price)+'. Grow your pig beyond its '+fmt(capacity)+' capacity.')}else{tell('You need '+fmt(h.price-coins)+' more coins.')}render()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelector('.scroller').scrollTop=0;render()});document.querySelector('#coins').onchange=e=>{coins=+e.target.value;render()};document.querySelector('#capacity').onchange=e=>{capacity=+e.target.value;render()};document.querySelector('#reset').onclick=()=>{owned=new Set(originalOwned);shown='villa';coins=2500000;capacity=96904045;filter='all';document.querySelector('#coins').value=coins;document.querySelector('#capacity').value=capacity;render()};document.querySelector('.close').onclick=()=>{document.querySelector('.shell').classList.add('closed');document.querySelector('.reopen').classList.add('on')};document.querySelector('.reopen').onclick=()=>{document.querySelector('.shell').classList.remove('closed');document.querySelector('.reopen').classList.remove('on')};document.querySelectorAll('.rail button:not(.selected)').forEach(b=>b.onclick=()=>tell('This design prototype covers the Home catalogue.'));render();
</script></body></html>'''
html = html.replace('width:min(1040px,100%);height:min(720px,', 'width:min(1020px,100%);height:min(578px,')
html = html.replace('color:#000;', 'color:var(--ink);')
(ROOT/'ui/catalogue.html').write_text(html.replace('__DATA__',json.dumps(houses)),encoding='utf-8')
print('Built catalogue prototype and 18-house design data.')
